"use client";

import Link from "next/link";
import { Label, Panel } from "@/components/ui";
import { useEffect, useState } from "react";

const SECTORS = [
  { id: "sanguinet", name: "Sanguinet (principal)" },
  { id: "cazaux", name: "Cazaux" },
  { id: "biscarrosse", name: "Biscarrosse" },
  { id: "parentis", name: "Parentis-en-Born" },
];

export default function ParametresPage() {
  const [name, setName] = useState("");
  const [sectorId, setSectorId] = useState("sanguinet");
  const [notifications, setNotifications] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  useEffect(() => {
    void fetch("/api/admin")
      .then((r) => r.json())
      .then((d) => {
        setName(d.config?.anglerName ?? "");
        setSectorId(d.config?.sectorId ?? "sanguinet");
        setNotifications(Boolean(d.config?.notifications));
      });
  }, []);

  async function save() {
    if (notifications && typeof Notification !== "undefined" && Notification.permission === "default") {
      await Notification.requestPermission();
    }
    const res = await fetch("/api/admin/weights", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ anglerName: name, sectorId, notifications }),
    });
    setMsg(res.ok ? "Enregistré. Rechargez l'accueil pour le nouveau secteur." : "Échec");
  }

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-semibold">Paramètres</h1>
      <Panel>
        <Label>Profil local</Label>
        <p className="mt-1 text-xs text-mist-500">Pas de compte cloud en V1 — stockage serveur local.</p>
        <input
          className="field mt-3"
          placeholder="Votre nom / pseudo"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
      </Panel>
      <Panel>
        <Label>Secteur</Label>
        <p className="mt-1 text-xs text-mist-500">
          Sanguinet reste le territoire principal. Les autres points changent la météo, pas un modèle calibré.
        </p>
        <select className="field mt-3" value={sectorId} onChange={(e) => setSectorId(e.target.value)}>
          {SECTORS.map((s) => (
            <option key={s.id} value={s.id}>
              {s.name}
            </option>
          ))}
        </select>
      </Panel>
      <Panel>
        <Label>Alertes navigateur</Label>
        <label className="mt-3 flex items-center gap-2 text-sm text-mist-300">
          <input type="checkbox" checked={notifications} onChange={(e) => setNotifications(e.target.checked)} />
          Notifier une fenêtre favorable (si le navigateur le permet)
        </label>
      </Panel>
      <button onClick={() => void save()} className="w-full rounded-xl bg-teal py-3 font-semibold text-ink-950">
        Enregistrer
      </button>
      {msg && <p className="text-sm text-mist-300">{msg}</p>}
      <Panel>
        <Label>Liens</Label>
        <div className="mt-3 flex flex-col gap-2 text-sm">
          <Link className="text-teal" href="/sources">
            Sources & méthodologie
          </Link>
          <Link className="text-teal" href="/admin">
            Administration du moteur
          </Link>
        </div>
      </Panel>
    </div>
  );
}

import { buildSnapshot } from "@/lib/services/snapshot";
import { HourlyTimeline } from "@/components/HourlyTimeline";
import { TrendChart } from "@/components/TrendChart";
import { Label, Panel, KindTag, scoreColor } from "@/components/ui";
import { cardinalFromDeg, cardinalLong, formatDate, formatTime } from "@/lib/format";

export const dynamic = "force-dynamic";

export default async function PrevisionPage() {
  const snap = await buildSnapshot();
  if (!snap.ok) {
    return (
      <Panel>
        <p className="text-signal-mid">Donnée indisponible</p>
      </Panel>
    );
  }

  return (
    <div className="space-y-4">
      <h1 className="text-2xl font-semibold">Prévision</h1>
      <p className="text-sm text-mist-500">24 h · 48 h · 72 h · 7 jours — source unique Open-Meteo.</p>

      <Panel>
        <Label>Timeline IF</Label>
        <div className="mt-3">
          <HourlyTimeline points={snap.hourly.slice(0, 24)} />
        </div>
      </Panel>

      <Panel>
        <Label>IF 72 h — maintenant et meilleures heures</Label>
        <TrendChart points={snap.hourly} metric="ifScore" />
      </Panel>
      <Panel>
        <Label>Pression 72 h</Label>
        <TrendChart points={snap.hourly} metric="pressureHpa" />
      </Panel>
      <Panel>
        <Label>Vent 72 h</Label>
        <TrendChart points={snap.hourly} metric="windKmh" />
      </Panel>

      <Panel>
        <div className="flex items-center justify-between">
          <Label>7 jours</Label>
          <KindTag kind="prévision" />
        </div>
        <div className="mt-3 divide-y divide-white/5">
          {snap.daily.map((d) => (
            <div key={d.date} className="flex flex-wrap items-center justify-between gap-2 py-3">
              <span className="w-40 text-mist-300">{formatDate(d.date)}</span>
              <span className={`font-mono tabular ${scoreColor(d.ifScore ?? null)}`}>
                IF {d.ifScore ?? "—"}
              </span>
              <span className="font-mono tabular">
                {d.tMin ?? "—"}° / {d.tMax ?? "—"}°
              </span>
              <span className="text-sm text-mist-500">
                {d.rain != null ? `${d.rain.toFixed(1)} mm` : "pluie n/d"} ·{" "}
                {d.windMax != null ? `${Math.round(d.windMax)} km/h` : "vent n/d"}{" "}
                {cardinalLong(cardinalFromDeg(d.windDir))}
              </span>
              <span className="text-xs text-mist-500">
                {formatTime(d.sunrise)} – {formatTime(d.sunset)}
              </span>
            </div>
          ))}
        </div>
      </Panel>

      {snap.window && (
        <Panel>
          <Label>Meilleur créneau</Label>
          <p className={`mt-2 text-xl ${scoreColor(snap.window.peak)}`}>
            {formatTime(snap.window.from)} → {formatTime(snap.window.to)} · IF {snap.window.peak}
          </p>
        </Panel>
      )}
    </div>
  );
}

"use client";

import { useEffect } from "react";
import type { FishingAlert } from "@/lib/types";

export function AlertNotify({
  alerts,
  enabled,
}: {
  alerts: FishingAlert[];
  enabled: boolean;
}) {
  useEffect(() => {
    if (!enabled || !alerts.length || typeof Notification === "undefined") return;
    if (Notification.permission === "default") {
      void Notification.requestPermission();
      return;
    }
    if (Notification.permission !== "granted") return;
    const top = alerts[0];
    new Notification(top.title, { body: top.body, icon: "/icon.svg" });
  }, [alerts, enabled]);
  return null;
}

"use client";

import { useState } from "react";
import type { SpeciesId } from "@/lib/types";
import { Label } from "./ui";

const SPECIES: SpeciesId[] = ["brochet", "sandre", "perche", "black-bass", "silure", "anguille"];

export function CatchForm({ onSaved }: { onSaved: () => void }) {
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  async function submit(form: HTMLFormElement) {
    setBusy(true);
    setMsg(null);
    const res = await fetch("/api/catches", {
      method: "POST",
      body: new FormData(form),
    });
    setBusy(false);
    if (!res.ok) {
      setMsg("Enregistrement impossible");
      return;
    }
    setMsg("Capture enregistrée — météo associée automatiquement.");
    form.reset();
    onSaved();
  }

  const today = new Date().toISOString().slice(0, 10);
  const time = new Date().toTimeString().slice(0, 5);

  return (
    <form
      className="space-y-3"
      onSubmit={(e) => {
        e.preventDefault();
        void submit(e.currentTarget);
      }}
    >
      <Label>Nouvelle capture</Label>
      <div className="grid grid-cols-2 gap-3">
        <input name="date" type="date" defaultValue={today} className="field" required />
        <input name="time" type="time" defaultValue={time} className="field" required />
        <select name="species" className="field col-span-2" defaultValue="brochet">
          {SPECIES.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
        <input name="lengthCm" type="number" step="0.1" placeholder="Taille cm" className="field" />
        <input name="weightKg" type="number" step="0.01" placeholder="Poids kg" className="field" />
        <input name="lure" placeholder="Leurre" className="field" />
        <input name="technique" placeholder="Technique" className="field" />
        <input name="depthM" type="number" step="0.1" placeholder="Profondeur m" className="field" />
        <input name="lat" type="number" step="0.0001" placeholder="Latitude" className="field" />
        <input name="lon" type="number" step="0.0001" placeholder="Longitude" className="field col-span-2" />
        <input name="photo" type="file" accept="image/*" className="field col-span-2" />
        <textarea name="comment" placeholder="Commentaire" className="field col-span-2 min-h-20" />
      </div>
      <button
        disabled={busy}
        className="w-full rounded-xl bg-teal py-3 font-semibold text-ink-950 disabled:opacity-50"
      >
        {busy ? "Enregistrement…" : "Enregistrer"}
      </button>
      {msg && <p className="text-sm text-mist-300">{msg}</p>}
    </form>
  );
}

import type { SnapshotOk } from "@/lib/services/snapshot";
import { cardinalLong, fmtNum } from "@/lib/format";
import { KindTag, Label, Panel } from "./ui";

export function ConditionCards({ snap }: { snap: SnapshotOk }) {
  const d12 = snap.current.pressureDeltas.d12;
  const sign = d12 != null ? (d12 > 0 ? "+" : "") : "";
  const cards = [
    {
      k: "Eau",
      v: snap.water.tempC != null ? `${snap.water.tempC.toFixed(1)} °C` : "Donnée indisponible",
      s: `Δ24h ${snap.water.delta24h > 0 ? "+" : ""}${snap.water.delta24h} °C · anomalie ${snap.water.anomaly > 0 ? "+" : ""}${snap.water.anomaly}`,
      tag: snap.water.kind,
    },
    {
      k: "Pression",
      v: fmtNum(snap.current.pressureHpa, 0, "hPa"),
      s: d12 != null ? `${sign}${d12.toFixed(1)} hPa / 12h` : "Variation indisponible",
      tag: "prévision",
    },
    {
      k: "Vent",
      v: fmtNum(snap.current.windKmh, 0, "km/h"),
      s: `${cardinalLong(snap.current.windCardinal)}${snap.current.windGustKmh != null ? ` · rafales ${Math.round(snap.current.windGustKmh)}` : ""}`,
      tag: "mesure modèle",
    },
    {
      k: "Nuages",
      v: fmtNum(snap.current.cloudPct, 0, "%"),
      s:
        snap.current.precipMm != null && snap.current.precipMm > 0
          ? `${snap.current.precipMm.toFixed(1)} mm`
          : "Précipitations nulles ou faibles",
      tag: "prévision",
    },
  ];

  return (
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
      {cards.map((c) => (
        <Panel key={c.k}>
          <div className="flex items-start justify-between gap-2">
            <Label>{c.k}</Label>
            <KindTag kind={c.tag} />
          </div>
          <p className="mt-2 font-mono text-2xl tabular text-mist-100">{c.v}</p>
          <p className="mt-1 text-xs text-mist-500">{c.s}</p>
        </Panel>
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";
import { formatTime } from "@/lib/format";
import type { FishingPlanSlot, SpeciesId } from "@/lib/types";
import { Label, Panel, scoreColor } from "./ui";

const SPECIES: { id: SpeciesId | "tous"; label: string }[] = [
  { id: "tous", label: "Tous carnassiers" },
  { id: "brochet", label: "Brochet" },
  { id: "sandre", label: "Sandre" },
  { id: "perche", label: "Perche" },
  { id: "black-bass", label: "Black-bass" },
  { id: "silure", label: "Silure" },
  { id: "anguille", label: "Anguille" },
];

function localInputValue(d = new Date()) {
  const t = new Date(d.getTime() - d.getTimezoneOffset() * 60000);
  return t.toISOString().slice(0, 16);
}

export function GoFishing() {
  const [open, setOpen] = useState(false);
  const [duration, setDuration] = useState(4);
  const [depart, setDepart] = useState(localInputValue);
  const [species, setSpecies] = useState<SpeciesId | "tous">("brochet");
  const [slots, setSlots] = useState<FishingPlanSlot[] | null>(null);
  const [loading, setLoading] = useState(false);

  async function run() {
    setLoading(true);
    const startIso = new Date(depart).toISOString();
    const res = await fetch("/api/fishing/plan", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        startIso,
        durationHours: duration,
        species,
      }),
    });
    const json = await res.json();
    setSlots(json.slots ?? []);
    setLoading(false);
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="w-full rounded-2xl bg-teal px-4 py-4 text-base font-semibold text-ink-950 shadow-panel touch-target"
      >
        Je vais pêcher
      </button>
      {open && (
        <div className="fixed inset-0 z-50 grid place-items-end bg-black/70 p-3 sm:place-items-center">
          <Panel className="w-full max-w-lg bg-ink-900">
            <div className="flex items-center justify-between">
              <Label>Plan de pêche</Label>
              <button type="button" onClick={() => setOpen(false)} className="text-mist-500">
                Fermer
              </button>
            </div>
            <p className="mt-2 text-sm text-mist-300">
              Départ, durée, espèce → plan horaire. La session est enregistrée dans le journal.
            </p>
            <label className="mt-4 block text-sm text-mist-300">
              Heure de départ
              <input
                type="datetime-local"
                value={depart}
                onChange={(e) => setDepart(e.target.value)}
                className="mt-1 w-full rounded-lg border border-white/10 bg-ink-800 px-3 py-2"
              />
            </label>
            <label className="mt-3 block text-sm text-mist-300">
              Durée (heures)
              <input
                type="number"
                min={1}
                max={12}
                value={duration}
                onChange={(e) => setDuration(Number(e.target.value))}
                className="mt-1 w-full rounded-lg border border-white/10 bg-ink-800 px-3 py-2"
              />
            </label>
            <label className="mt-3 block text-sm text-mist-300">
              Espèce
              <select
                value={species}
                onChange={(e) => setSpecies(e.target.value as SpeciesId | "tous")}
                className="mt-1 w-full rounded-lg border border-white/10 bg-ink-800 px-3 py-2"
              >
                {SPECIES.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.label}
                  </option>
                ))}
              </select>
            </label>
            <button
              type="button"
              onClick={run}
              className="mt-4 w-full rounded-xl bg-teal py-3 font-semibold text-ink-950"
            >
              {loading ? "Calcul…" : "Générer le plan"}
            </button>
            {slots && (
              <div className="mt-4 space-y-2">
                {slots.length === 0 && (
                  <p className="text-sm text-signal-mid">Pas de créneau calculable sur cette fenêtre.</p>
                )}
                {slots.map((s) => (
                  <div
                    key={s.from}
                    className={`rounded-xl border px-3 py-3 ${
                      s.best ? "border-teal bg-teal/10" : "border-white/10"
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span>
                        {formatTime(s.from)}–{formatTime(s.to)}
                      </span>
                      <span className={`font-mono tabular ${scoreColor(s.ifScore)}`}>IF {s.ifScore}</span>
                    </div>
                    <p className="text-xs text-mist-500">
                      {s.best ? "MEILLEURE FENÊTRE · " : ""}
                      {s.label}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </Panel>
        </div>
      )}
    </>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { bestFishingWindows, nowHourIndex } from "@/lib/engines/explain";
import { formatTime } from "@/lib/format";
import type { HourlyPoint } from "@/lib/types";
import { scoreBg, scoreColor } from "./ui";

export function HourlyTimeline({ points }: { points: HourlyPoint[] }) {
  const hours = points.slice(0, 24);
  const nowIdx = nowHourIndex(hours);
  const peaks = new Set(bestFishingWindows(hours, 3).map((w) => w.peakIdx));
  const nowRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    nowRef.current?.scrollIntoView({ inline: "center", block: "nearest", behavior: "smooth" });
  }, [nowIdx]);

  return (
    <div className="flex gap-2 overflow-x-auto pb-2">
      {hours.map((h, i) => {
        const isNow = i === nowIdx;
        const isPeak = peaks.has(i);
        return (
          <div
            key={h.time}
            ref={isNow ? nowRef : undefined}
            className={`relative min-w-[58px] rounded-xl px-2 py-3 text-center ${scoreBg(h.ifScore)} ${
              isNow ? "ring-2 ring-mist-100" : ""
            } ${isPeak ? "ring-2 ring-gold" : ""}`}
          >
            {isNow && (
              <p className="absolute -top-2 left-1/2 -translate-x-1/2 rounded bg-mist-100 px-1 text-[9px] font-semibold uppercase tracking-wide text-ink-950">
                now
              </p>
            )}
            {isPeak && !isNow && (
              <p className="absolute -top-2 left-1/2 -translate-x-1/2 rounded bg-gold px-1 text-[9px] font-semibold uppercase tracking-wide text-ink-950">
                pic
              </p>
            )}
            <p className="text-[10px] text-mist-500">{formatTime(h.time)}</p>
            <p className={`mt-1 font-mono text-lg tabular ${scoreColor(h.ifScore)}`}>
              {h.ifScore ?? "—"}
            </p>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { LAKE, LAKE_GEOJSON, LAKE_POLYGON, LAKE_ZONES } from "@/lib/lake";
import { downwindBearing, exposedShore } from "@/lib/engines/wind";
import type { CatchRecord, SavedLocation } from "@/lib/types";

function pinEl(name: string, kind: "primary" | "spot" | "catch") {
  const el = document.createElement("div");
  el.className = `lake-pin lake-pin-${kind}`;
  el.innerHTML = `<span class="lake-pin-dot"></span><span class="lake-pin-name">${name}</span>`;
  return el;
}

export function LakeMap({
  windDirDeg,
  windKmh,
  catches = [],
  locations = [],
}: {
  windDirDeg: number | null;
  windKmh: number | null;
  catches?: CatchRecord[];
  locations?: SavedLocation[];
}) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const map = new maplibregl.Map({
      container: ref.current,
      style: "https://tiles.openfreemap.org/styles/dark",
      center: [LAKE.center.lon, LAKE.center.lat],
      zoom: 11,
      attributionControl: true,
    });
    map.addControl(new maplibregl.NavigationControl({ showCompass: true }), "top-right");

    map.fitBounds(
      [
        [LAKE.bounds.west, LAKE.bounds.south],
        [LAKE.bounds.east, LAKE.bounds.north],
      ],
      { padding: 48, duration: 0 },
    );

    map.on("load", () => {
      map.addSource("lake", {
        type: "geojson",
        data: LAKE_GEOJSON,
      });
      map.addLayer({
        id: "lake-fill",
        type: "fill",
        source: "lake",
        paint: { "fill-color": "#2ec4b6", "fill-opacity": 0.28 },
      });
      map.addLayer({
        id: "lake-line",
        type: "line",
        source: "lake",
        paint: { "line-color": "#7ee8dc", "line-width": 1.6 },
      });

      if (windDirDeg != null && windKmh != null) {
        const to = downwindBearing(windDirDeg);
        const rad = (to * Math.PI) / 180;
        const len = 0.035 + Math.min(windKmh, 40) / 900;
        const from: [number, number] = [LAKE.center.lon, LAKE.center.lat];
        const dest: [number, number] = [
          LAKE.center.lon + Math.sin(rad) * len,
          LAKE.center.lat + Math.cos(rad) * len,
        ];
        map.addSource("wind", {
          type: "geojson",
          data: {
            type: "Feature",
            properties: {},
            geometry: { type: "LineString", coordinates: [from, dest] },
          },
        });
        map.addLayer({
          id: "wind-line",
          type: "line",
          source: "wind",
          paint: { "line-color": "#d4a853", "line-width": 3 },
        });
        const ang = Math.atan2(dest[0] - from[0], dest[1] - from[1]);
        const hs = 0.011;
        const head: [number, number][] = [
          [
            dest[0] + Math.sin(ang + Math.PI * 0.82) * hs,
            dest[1] + Math.cos(ang + Math.PI * 0.82) * hs,
          ],
          dest,
          [
            dest[0] + Math.sin(ang - Math.PI * 0.82) * hs,
            dest[1] + Math.cos(ang - Math.PI * 0.82) * hs,
          ],
        ];
        map.addSource("wind-head", {
          type: "geojson",
          data: {
            type: "Feature",
            properties: {},
            geometry: { type: "LineString", coordinates: head },
          },
        });
        map.addLayer({
          id: "wind-head",
          type: "line",
          source: "wind-head",
          paint: { "line-color": "#d4a853", "line-width": 3, "line-cap": "round" },
        });

        const exposed = exposedShore(LAKE_POLYGON, windDirDeg);
        if (exposed.length > 1) {
          map.addSource("exposed", {
            type: "geojson",
            data: {
              type: "Feature",
              properties: {},
              geometry: { type: "LineString", coordinates: exposed },
            },
          });
          map.addLayer({
            id: "exposed-line",
            type: "line",
            source: "exposed",
            paint: { "line-color": "#ff6b4a", "line-width": 4, "line-opacity": 0.9 },
          });
        }
      }

      LAKE_ZONES.forEach((z) => {
        new maplibregl.Marker({
          element: pinEl(z.name, z.id === "sanguinet" ? "primary" : "spot"),
          anchor: "left",
        })
          .setLngLat([z.lon, z.lat])
          .addTo(map);
      });

      catches
        .filter((c) => c.lat != null && c.lon != null)
        .forEach((c) => {
          new maplibregl.Marker({
            element: pinEl(`${c.species}`, "catch"),
            anchor: "left",
          })
            .setLngLat([c.lon as number, c.lat as number])
            .setPopup(new maplibregl.Popup().setText(`${c.species} ${c.date}`))
            .addTo(map);
        });

      locations.forEach((l) => {
        new maplibregl.Marker({
          element: pinEl(l.name, "catch"),
          anchor: "left",
        })
          .setLngLat([l.lon, l.lat])
          .addTo(map);
      });
    });

    return () => map.remove();
  }, [windDirDeg, windKmh, catches, locations]);

  return (
    <div className="relative">
      <div ref={ref} className="h-[560px] w-full overflow-hidden rounded-2xl border border-white/10" />
      <div className="pointer-events-none absolute bottom-3 left-3 rounded-xl border border-white/10 bg-ink-950/80 px-3 py-2 text-[11px] text-mist-300 backdrop-blur-sm">
        <p>
          <span className="mr-1 inline-block h-2 w-2 rounded-full bg-teal" />
          Contour OSM
        </p>
        <p>
          <span className="mr-1 inline-block h-0.5 w-4 bg-gold align-middle" />
          Vent (vers où il pousse)
        </p>
        <p>
          <span className="mr-1 inline-block h-0.5 w-4 bg-signal-bad align-middle" />
          Rive exposée
        </p>
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { Label } from "./ui";

export function LocationForm() {
  const router = useRouter();
  const [msg, setMsg] = useState<string | null>(null);

  async function submit(form: FormData) {
    const res = await fetch("/api/locations", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: form.get("name"),
        lat: Number(form.get("lat")),
        lon: Number(form.get("lon")),
      }),
    });
    setMsg(res.ok ? "Spot enregistré" : "Impossible d'enregistrer");
    if (res.ok) router.refresh();
  }

  return (
    <form
      className="space-y-3"
      onSubmit={(e) => {
        e.preventDefault();
        void submit(new FormData(e.currentTarget));
      }}
    >
      <Label>Spot personnel</Label>
      <p className="text-xs text-mist-500">Vos zones, pas une bathymétrie publique.</p>
      <input name="name" placeholder="Nom du spot" className="field" required />
      <div className="grid grid-cols-2 gap-2">
        <input name="lat" type="number" step="0.0001" placeholder="Lat" className="field" required />
        <input name="lon" type="number" step="0.0001" placeholder="Lon" className="field" required />
      </div>
      <button className="w-full rounded-xl bg-teal py-3 font-semibold text-ink-950">Ajouter</button>
      {msg && <p className="text-sm text-mist-300">{msg}</p>}
    </form>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";

export function RefreshButton() {
  const router = useRouter();
  const [busy, setBusy] = useState(false);

  async function run() {
    setBusy(true);
    await fetch("/api/admin/refresh", { method: "POST" });
    router.refresh();
    setBusy(false);
  }

  return (
    <button
      type="button"
      onClick={() => void run()}
      className="rounded-lg border border-white/15 px-3 py-2 text-sm text-mist-300 touch-target"
    >
      {busy ? "Mise à jour…" : "Actualiser"}
    </button>
  );
}

